function readZip(buffer) { const bytes = new Uint8Array(buffer), view = new DataView(buffer), decoder = new TextDecoder(), files = {}; const read16 = p => view.getUint16(p, true), read32 = p => view.getUint32(p, true); let pos = 0; while (pos + 30 <= bytes.length) { const signature = read32(pos); if (signature === 0x04034b50) { const method = read16(pos + 8), compressedSize = read32(pos + 18), nameLength = read16(pos + 26), extraLength = read16(pos + 28), name = decoder.decode(bytes.slice(pos + 30, pos + 30 + nameLength)), dataStart = pos + 30 + nameLength + extraLength; if (method !== 0) throw new Error("This backup uses an unsupported ZIP compression method."); files[name] = decoder.decode(bytes.slice(dataStart, dataStart + compressedSize)); pos = dataStart + compressedSize; } else if (signature === 0x02014b50 || signature === 0x06054b50) break; else throw new Error("Invalid ZIP backup."); } return files; }
function downloadBlob(name, blob) { const url = URL.createObjectURL(blob), link = document.createElement("a"); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
function exportBackup(filename = "labflow-backup.zip", message = "Backup exported") { const manifest = { format: "LabFlow browser backup", version: 1, exportedAt: new Date().toISOString() }; const files = { "manifest.json": JSON.stringify(manifest, null, 2), "labflow-data.json": JSON.stringify(state, null, 2), "templates.json": JSON.stringify(templates, null, 2), "measurements.json": JSON.stringify(measurementBoard, null, 2) }; downloadBlob(filename, new Blob([zipBytes(files)], { type: "application/zip" })); toast(message); }
function validateImportedState(data, templateData, measurements) { const dateOk = value => value == null || validDate(new Date(value)); const experimentOk = data && Array.isArray(data.experiments) && Array.isArray(data.blocks) && data.experiments.every(exp => exp && typeof exp.id === "string" && typeof exp.template === "string" && Array.isArray(exp.stages) && exp.stages.length > 0 && exp.stages.filter(stage => stage.status === "current").length <= 1 && exp.stages.every(stage => stage && typeof stage.name === "string" && ["current", "upcoming", "completed"].includes(stage.status) && dateOk(stage.startedAt) && dateOk(stage.readyAt) && dateOk(stage.completedAt))); const templatesOk = templateData && Object.values(templateData).every(template => template && typeof template.name === "string" && Array.isArray(template.stages) && template.stages.length > 0 && template.stages.every(stage => stage && typeof stage.name === "string" && Number.isFinite(Number(stage.duration)))); const measurementsOk = measurements && Array.isArray(measurements.samples) && Array.isArray(measurements.measurements) && Array.isArray(measurements.cells); return Boolean(experimentOk && templatesOk && measurementsOk); }
function importBackup(file) { if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const files = readZip(reader.result); const importedState = JSON.parse(files["labflow-data.json"]), importedTemplates = JSON.parse(files["templates.json"]), importedMeasurements = JSON.parse(files["measurements.json"]); if (!validateImportedState(importedState, importedTemplates, importedMeasurements)) throw new Error("Invalid LabFlow backup."); state = importedState; templates = importedTemplates; measurementBoard = importedMeasurements; normalizeMeasurementBoard(); save(); browserWrite(BROWSER_TEMPLATES_KEY, templates); saveMeasurementBoard(); closeModal(); render(); toast("Backup imported"); } catch (error) { toast(error.message || "Could not import backup"); } }; reader.readAsArrayBuffer(file); }
function settingsModal() { const current = localStorage.getItem("labflow-text-scale") || "standard"; const font = localStorage.getItem("labflow-display-font") || "system"; openModal(`<div class="modal-header"><div><h2 id="modalTitle">Settings</h2></div><button class="close" aria-label="Close">×</button></div><div class="field"><label for="textScaleSelect">Text size</label><select id="textScaleSelect" class="settings-select"><option value="standard"${current === "standard" ? " selected" : ""}>Standard</option><option value="large"${current === "large" ? " selected" : ""}>Large</option><option value="xlarge"${current === "xlarge" ? " selected" : ""}>Extra large</option></select></div><div class="field"><label for="displayFontSelect">Display font</label><select id="displayFontSelect" class="settings-select"><option value="system"${font === "system" ? " selected" : ""}>System</option><option value="gochi"${font === "gochi" ? " selected" : ""}>Gochi Hand</option><option value="marker"${font === "marker" ? " selected" : ""}>Permanent Marker</option><option value="damion"${font === "damion" ? " selected" : ""}>Damion</option></select></div><div class="settings-backup"><label>Backup</label><div class="backup-actions"><button type="button" class="secondary-button" id="exportBackupButton">Export</button><button type="button" class="secondary-button" id="importBackupButton">Import</button><input type="file" id="importBackupFile" accept=".zip,application/zip" hidden /></div><span class="subtle">ZIP includes experiments, procedures, and measurements.</span></div>`); document.getElementById("textScaleSelect").onchange = event => { applyTextScale(event.target.value); closeModal(); }; document.getElementById("displayFontSelect").onchange = event => { applyDisplayFont(event.target.value); closeModal(); }; document.getElementById("exportBackupButton").onclick = exportBackup; document.getElementById("importBackupButton").onclick = () => { exportBackup("labflow-before-import.zip", "Current data backed up"); window.setTimeout(() => document.getElementById("importBackupFile").click(), 120); }; document.getElementById("importBackupFile").onchange = event => importBackup(event.target.files[0]); }
function toast(message) { const el = document.getElementById("toast"); el.textContent = message; el.classList.add("show"); setTimeout(() => el.classList.remove("show"), 2800); }
document.getElementById("quickExportButton")?.addEventListener("click", exportBackup);
document.addEventListener("click", e => { if (e.target === document.getElementById("modalBackdrop")) { closeModal(); return; } if (e.target.matches(".close")) { closeModal(); return; } if (document.getElementById("modalBackdrop")?.hidden === false) return; if (e.target.closest?.("#settingsButton")) settingsModal(); }); document.addEventListener("keydown", e => { if (e.key === "Escape" && document.getElementById("modalBackdrop")?.hidden === false) { e.preventDefault(); closeModal(); } });
applyTextScale(localStorage.getItem("labflow-text-scale") || "standard"); applyDisplayFont(localStorage.getItem("labflow-display-font") || "system"); render(); window.addEventListener("hashchange", render); loadMeasurementBoard(); loadState();
function renumberProcedureStages() { document.querySelectorAll("#procedureStageRows .procedure-stage-index").forEach((node, index) => { node.textContent = index + 1; }); }



function updateProcedureMeasurementHint(row) { const name = row.querySelector(".procedure-stage-name").value.trim().toLowerCase(); const hint = row.querySelector(".procedure-stage-hint"); if (hint) hint.hidden = !["measurement", "measurements", "measurment", "measurments"].includes(name); }
function addProcedureStageRow(stage) { const holder = document.getElementById("procedureStageRows"); const row = document.createElement("div"); row.className = "procedure-edit-row"; row.innerHTML = '<span class="procedure-stage-index">' + (holder.children.length + 1) + '</span><input class="procedure-stage-name" required><input class="procedure-stage-duration" type="number" min="0" step="any" value="24"><select class="procedure-stage-unit"><option value="h">h</option><option value="min">min</option></select><input class="procedure-stage-location" value="Main Lab"><button type="button" class="secondary-button" data-remove-stage>×</button><small class="procedure-stage-hint" hidden>Time shown is for one sample.</small>'; holder.appendChild(row); if (stage) { row.querySelector(".procedure-stage-name").value = stage.name || ""; const duration = Number(stage.duration) || 0; row.querySelector(".procedure-stage-duration").value = duration >= 1 || duration === 0 ? duration : Math.round(duration * 60); row.querySelector(".procedure-stage-unit").value = duration >= 1 || duration === 0 ? "h" : "min"; row.querySelector(".procedure-stage-location").value = stage.location || "Main Lab"; } row.querySelector(".procedure-stage-name").addEventListener("input", () => updateProcedureMeasurementHint(row)); row.querySelector("[data-remove-stage]").onclick = function () { row.remove(); renumberProcedureStages(); }; updateProcedureMeasurementHint(row); }
function procedureFormModal() { const editingName = procedureEditingName; const existing = editingName ? templates[editingName] : null; openModal('<div class="modal-header"><div><h2 id="modalTitle">' + (existing ? 'Edit Procedure' : 'New Procedure') + '</h2></div><button class="close" aria-label="Close">×</button></div><form class="form" id="procedureForm"><div class="field"><label>Procedure name</label><input id="procedureName" required></div><div class="field"><label>Stages</label><div id="procedureStageRows"></div><button type="button" class="secondary-button" id="addProcedureStage">+ Add stage</button></div><div class="form-actions"><button type="button" class="secondary-button close">Cancel</button><button class="primary-button">Save</button></div></form>'); document.getElementById("procedureName").value = editingName || ""; if (existing?.stages?.length) existing.stages.forEach(stage => addProcedureStageRow(stage)); else addProcedureStageRow(); document.getElementById("addProcedureStage").onclick = () => addProcedureStageRow(); document.getElementById("procedureForm").onsubmit = function (event) { event.preventDefault(); const name = document.getElementById("procedureName").value.trim(); const stages = Array.from(document.querySelectorAll(".procedure-edit-row")).map(row => ({ name: row.querySelector(".procedure-stage-name").value.trim(), duration: (Number(row.querySelector(".procedure-stage-duration").value) || 0) * (row.querySelector(".procedure-stage-unit").value === "min" ? 1 / 60 : 1), location: row.querySelector(".procedure-stage-location").value.trim() || "Main Lab" })); if (!stages.length || !name) return; if (editingName && editingName !== name) delete templates[editingName]; templates[name] = { name, stages }; browserWrite(BROWSER_TEMPLATES_KEY, templates); procedureEditingName = null; closeModal(); render(); toast(name + " procedure saved"); }; }
function newProcedureModal() { procedureEditingName = null; procedureFormModal(); }
function editProcedureModal(name) { if (!templates[name]) return; procedureEditingName = name; procedureFormModal(); }

document.addEventListener("dblclick", event => { const card = event.target.closest?.(".procedure-card"); if (card) editProcedureModal(card.dataset.procedure); });


function calendarEventReadyMarker(className, title, body, experimentId, start, end, blockId, lane, laneCount) { const detail = encodeURIComponent(JSON.stringify({ title: title, body: body })); const experimentAttr = experimentId ? ' data-calendar-experiment="' + experimentId + '"' : ''; const blockAttr = blockId ? ' data-calendar-block="' + blockId + '"' : ''; const startDate = start ? new Date(start) : null; const endDate = end ? new Date(end) : null; const hour = startDate ? startDate.getHours() + startDate.getMinutes() / 60 : 8; const duration = startDate && endDate ? Math.max(.5, (endDate - startDate) / 3600000) : .5; const top = Math.max(0, Math.min(24, hour)) * 56; const height = Math.max(24, Math.min(24, duration) * 56); const style = startDate ? ' style="top:' + top + 'px;height:' + height + 'px;--event-lane:' + (lane || 0) + ';--event-lanes:' + (laneCount || 1) + '"' : ''; const experiment = experimentId ? state.experiments.find(x => x.id === experimentId) : null; const tooltip = experiment ? experimentLabel(experiment) : title; const safeTooltip = String(tooltip).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); const ready = className.includes('ready-marker'); const visibleTitle = ready ? "<span class=\"ready-icon\" aria-hidden=\"true\">✓</span>" + escapeHtml(title) : escapeHtml(title); const visibleBody = escapeEventBody(body); return '<div class="calendar-event ' + className + '" data-calendar-detail="' + detail + '"' + experimentAttr + blockAttr + style + ' title="' + safeTooltip + '" aria-label="' + safeTooltip + '"><strong>' + visibleTitle + '</strong><span class="event-body">' + visibleBody + '</span></div>'; }
function calendarEvent(className, title, body, experimentId, start, end, blockId, lane, laneCount) { return calendarEventReadyMarker(className, title, body, experimentId, start, end, blockId, lane, laneCount); }

function detailStageEstimate(exp, index) {
  const currentIndex = exp.stages.findIndex(stage => stage.status === "current");
  if (index < currentIndex) return null;
  let cursor = currentIndex >= 0 && exp.stages[currentIndex].startedAt ? new Date(exp.stages[currentIndex].startedAt) : null;
  let targetStart = null;
  for (let i = currentIndex; i <= index; i += 1) {
    const stage = exp.stages[i];
    if (!stage) continue;
    if (i === currentIndex) { targetStart = stage.startedAt ? new Date(stage.startedAt) : null; if (stage.readyAt) cursor = new Date(stage.readyAt); }
    else if (i > currentIndex) {
      const start = stage.plannedStartAt ? new Date(stage.plannedStartAt) : cursor ? new Date(cursor.getTime() + DEFAULT_TRANSITION_HOURS * 3600000) : null;
      if (i === index) targetStart = start;
      cursor = start && stage.duration ? new Date(start.getTime() + calendarStageHours(stage, exp) * 3600000) : start;
    } else if (cursor && stage.duration) cursor = new Date(cursor.getTime() + calendarStageHours(stage, exp) * 3600000);
  }
  return targetStart && !Number.isNaN(targetStart.getTime()) ? targetStart : null;
}
function detailModal(id, focusStageName) {
  const e = state.experiments.find(x => x.id === id);
  const normalizedFocus = String(focusStageName || '').trim().toLowerCase();
  if (!e) return;
  const current = e.stages.find(x => x.status === "current");
  const currentIndex = current ? e.stages.indexOf(current) : -1;
  const next = current ? e.stages[currentIndex + 1] : null;
  const nextPlan = next?.plannedStartAt ? escapeHtml(next.name) + " · " + fmtDateTime(next.plannedStartAt) : next ? escapeHtml(next.name) + " · System suggestion" : "—";
  const workflow = e.stages.map((s, index) => {
    const isCurrent = s.status === "current";
    const estimate = isCurrent && s.readyAt ? new Date(s.readyAt) : detailStageEstimate(e, index);    const isFocused = normalizedFocus && s.name.trim().toLowerCase() === normalizedFocus;
    const locationHint = "";
    const displayEstimate = s.plannedStartAt ? new Date(s.plannedStartAt) : estimate; const timeHint = isCurrent && s.startedAt ? "Started<br>" + fmtDateTime(s.startedAt) : displayEstimate ? "Estimated<br>" + fmtDateTime(displayEstimate) : s.status === "completed" ? "Done" : "";
    return '<div class="stage ' + s.status + (isCurrent ? " is-current" : "") + (isFocused ? " is-focused" : "") + '"><span class="stage-dot">' + (s.status === "completed" ? "✓" : "") + '</span><div class="stage-info"><strong>' + escapeHtml(s.name) + '</strong><span>' + (s.duration ? (s.duration >= 1 ? s.duration + " h" : Math.round(s.duration * 60) + " min") + (isMeasurementStage(s) ? " / sample" : "") : "Duration variable") + '</span>' + locationHint + '</div><span class="stage-time">' + timeHint + '</span></div>';
  }).join("");
  const actions = current ? '<div class="detail-actions-heading">Edit</div><div class="detail-actions-row"><button type="button" class="secondary-button" id="editStartButton">Start time</button>' + (next ? '<button type="button" class="secondary-button" id="editPlannedTimeButton">Plan time</button>' : '<span></span>') + '</div><div class="detail-action-divider"></div><button class="primary-button" id="completeButton">Complete current step</button>' : "";
  const readyBox = next?.plannedStartAt ? "" : '<div><span>Ready</span><strong>' + (current?.readyAt ? fmtDateTime(current.readyAt) : "When you finish") + '</strong></div>';
  const plannedBox = next?.plannedStartAt ? '<div><span>Next planned start</span><strong>' + nextPlan + '</strong></div>' : "";
  openModal('<div class="detail-head"><div><h2 id="modalTitle">' + escapeHtml(e.template) + '</h2><div class="detail-meta"><span class="meta-chip">' + escapeHtml(Array.isArray(e.samples) ? e.samples.join(", ") : (e.batch || "Samples")) + '</span><span class="meta-chip">·</span><span class="meta-chip">' + escapeHtml(current?.location || "") + '</span></div></div><button class="close" aria-label="Close">×</button></div><div class="workflow">' + workflow + '</div><div class="current-box"><span class="eyebrow">Current stage</span><div class="current-grid"><div><span>Started</span><strong>' + (current?.startedAt ? fmtDateTime(current.startedAt) : "—") + '</strong></div>' + readyBox + '' + plannedBox + '<div><span>Location</span><strong>' + escapeHtml(current?.location || "—") + '</strong></div></div><div class="detail-footer">' + (current ? '<div class="detail-actions">' + actions + '</div>' : '') + '<button class="secondary-button" id="deleteButton">Delete</button></div></div>');
  document.getElementById("completeButton")?.addEventListener("click", () => completeChoice(id));
  document.getElementById("editStartButton")?.addEventListener("click", () => editStartTimeModal(id));
  document.getElementById("editPlannedTimeButton")?.addEventListener("click", () => editAllPlannedTimesInDetail(id));
  document.getElementById("deleteButton").onclick = () => deleteExperiment(id);
}

function detailTimeInputValue(value) {
  const date = value instanceof Date ? value : new Date(value);
  const pad = number => String(number).padStart(2, "0");
  const hour24 = date.getHours();
  return pad(date.getMonth() + 1) + "/" + pad(date.getDate()) + " " + pad(hour24 % 12 || 12) + ":" + pad(date.getMinutes()) + " " + (hour24 >= 12 ? "PM" : "AM");
}
function editAllPlannedTimesInDetail(id) {
  const e = state.experiments.find(x => x.id === id);
  if (!e) return;
  const currentIndex = e.stages.findIndex(stage => stage.status === "current");
  if (currentIndex < 0) return;
  const stageNodes = Array.from(document.querySelectorAll(".workflow .stage"));
  const editable = e.stages.map((stage, index) => ({ stage, index })).filter(item => item.index > currentIndex);
  if (!editable.length) return;
  stageNodes.forEach(node => node.classList.remove("is-focused"));
  editable.forEach(({ stage, index }) => {
    const node = stageNodes[index];
    const timeNode = node?.querySelector(".stage-time");
    if (!timeNode) return;
    const estimate = stage.plannedStartAt ? new Date(stage.plannedStartAt) : detailStageEstimate(e, index);
    const inputId = "planStageTime" + index;
    timeNode.innerHTML = '<label class="inline-plan-label" for="' + inputId + '">Plan start</label><input class="inline-plan-time" id="' + inputId + '" data-plan-stage-index="' + index + '" type="text" inputmode="text" maxlength="15" placeholder="MM/DD HH:mm AM/PM" value="' + (estimate ? detailTimeInputValue(estimate) : "") + '" />';
    setupLabTimeInput(inputId);
    if (estimate) {
      const input = document.getElementById(inputId);
      input.value = detailTimeInputValue(estimate);
      input.dispatchEvent(new Event("input", { bubbles: true }));
    }
  });
  const detailActions = document.querySelector(".detail-actions");
  if (!detailActions) return;
  detailActions.innerHTML = '<div class="detail-actions-heading">Plan time</div><div class="detail-plan-note">Edit the planned start time for each upcoming step.</div><div class="detail-actions-row"><button type="button" class="secondary-button" id="cancelPlanTimesButton">Cancel</button><button type="button" class="primary-button" id="savePlanTimesButton">Save planned times</button></div>';
  document.getElementById("cancelPlanTimesButton").onclick = () => detailModal(id);
  document.getElementById("savePlanTimesButton").onclick = () => {
    editable.forEach(({ stage, index }) => {
      const input = document.getElementById("planStageTime" + index);
      if (!input || !input.value.trim()) return;
      const when = parseLabTime(readLabTime(input.id));
      if (!Number.isNaN(when.getTime())) stage.plannedStartAt = when.toISOString();
    });
    save();
    closeModal();
    render();
    detailModal(id);
  };
}
